const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const point = ee.Geometry.Point(140.878144, 27.245974);
    const radius_km = 2;
    const buffer_geom = point.buffer(radius_km * 1000); // 2 km buffer

    const date1_start = '2013-12-01';
    const date1_end = '2013-12-15'; // A short window around Dec 8, 2013

    const date2_start = '2014-03-20';
    const date2_end = '2014-04-10'; // A short window around Mar 30, 2014

    // Landsat 8 SR bands for NDWI: Green (B3), NIR (B5)
    const L8_BANDS = ['B2', 'B3', 'B4', 'B5', 'B6', 'B7', 'pixel_qa']; // For cloud masking + NDWI

    // Function to mask clouds from Landsat 8 SR data.
    // Based on the 'pixel_qa' band.
    const maskL8sr = function(image) {
      // Bits 3 and 5 are cloud shadow and cloud, respectively.
      const cloudShadowBitMask = (1 << 3);
      const cloudsBitMask = (1 << 5);
      // Get the pixel QA band.
      const qa = image.select('pixel_qa');
      // Both flags should be set to zero, indicating clear conditions.
      const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                   .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
      return image.updateMask(mask).select(L8_BANDS.slice(0, -1)) // Select all but pixel_qa
                  .copyProperties(image, ['system:time_start']); // Keep time property
    };

    // Function to calculate NDWI and classify land/water
    const classifyLand = function(image) {
      const ndwi = image.normalizedDifference(['B3', 'B5']).rename('NDWI');
      // Land pixels typically have NDWI < 0. Let's use a simple threshold.
      // We are looking for "islands", so we want to identify land.
      const land = ndwi.lt(0).rename('land'); // 1 for land, 0 for water
      return land.updateMask(land); // Mask out water for connected components
    };

    // Function to process an image collection for a given period
    const processImages = async (startDate, endDate, periodName) => {
      let collection = ee.ImageCollection('LANDSAT/LC08/C01/T1_SR')
          .filterBounds(buffer_geom)
          .filterDate(startDate, endDate)
          .map(maskL8sr)
          .map(classifyLand);

      let collectionSize = await collection.size().getInfo();
      console.log(`${periodName} Images before filtering: ${collectionSize}`);

      if (collectionSize === 0) {
        return { islandCount: 'C1', imageCount: 0 };
      }

      // Take the median of the collection to get a single clear image.
      const composite = collection.median();

      const landPixels = await composite.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: buffer_geom,
        scale: 30, // Landsat resolution
        maxPixels: 1e9
      }).get('land').getInfo();

      if (landPixels === 0) {
        console.log(`Warning: No valid land pixels found for ${periodName} after cloud masking.`);
        return { islandCount: 'C2', imageCount: collectionSize };
      }

      // Apply connected components to identify individual islands.
      // minPixels sets a threshold for the minimum size of a component to be considered.
      // This helps filter out noise or very small specks. A value of 10-50 pixels is reasonable for a 30m resolution.
      const connected = composite.connectedComponents({
        connectedness: 8,
        maxSize: 100000 // Max size for a component in pixels (e.g., 900000 pixels = 0.81 km^2)
      });

      // Get the number of unique components (islands).
      // We're interested in the number of unique labels.
      // Use reduceRegion with a frequency reducer on the 'labels' band.
      const islandFrequency = await connected.reduceRegion({
        reducer: ee.Reducer.frequencyHistogram(),
        geometry: buffer_geom,
        scale: 30,
        maxPixels: 1e9
      }).get('labels').getInfo();

      // The frequency histogram returns a dictionary where keys are labels and values are pixel counts.
      // The number of keys is the number of distinct islands.
      let numIslands = 0;
      if (islandFrequency) {
        numIslands = Object.keys(islandFrequency).length;
      }

      return { islandCount: numIslands, imageCount: collectionSize };
    };

    // Process for Date 1
    const result1 = await processImages(date1_start, date1_end, '2013-12 Period');
    if (result1.islandCount === 'C1' || result1.islandCount === 'C2') {
      console.log(`<answer>${result1.islandCount}</answer>`);
      return;
    }
    console.log(`2013-12 Period: Images: ${result1.imageCount}, Islands: ${result1.islandCount}`);

    // Process for Date 2
    const result2 = await processImages(date2_start, date2_end, '2014-03 Period');
    if (result2.islandCount === 'C1' || result2.islandCount === 'C2') {
      console.log(`<answer>${result2.islandCount}</answer>`);
      return;
    }
    console.log(`2014-03 Period: Images: ${result2.imageCount}, Islands: ${result2.islandCount}`);

    // Check conditions
    const conditionMet = (result1.islandCount === 2) && (result2.islandCount === 1);

    if (typeof result1.islandCount !== 'number' || typeof result2.islandCount !== 'number') {
      console.log('Error: Island count is not a number.');
      console.log('<answer>C3</answer>');
    } else if (conditionMet) {
      console.log('<answer>A</answer>');
    } else {
      console.log('<answer>B</answer>');
    }

  } catch (error) {
    console.error('An error occurred:', error);
    if (error.message.includes('not found') || error.message.includes('Cannot read property') || error.message.includes('Invalid argument')) {
      console.log('<answer>D</answer>');
    } else {
      console.log('<answer>C3</answer>');
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
